30	pub(crate) enum InterpolatedStringLayout {
31	    /// Original f/t-string is flat.
32	    /// Don't break expressions to keep the string flat.
33	    Flat,
34	    /// Original f/t-string has multiline expressions in the replacement fields.
35	    /// Allow breaking expressions across multiple lines.
