23	#[test]
24	fn generate_inline_tests() -> Result<()> {
25	    let parser_dir = project_root().join("crates/ruff_python_parser/src/");
26	    let tests = TestCollection::try_from(parser_dir.as_path())?;
27	
28	    let mut test_files = TestFiles::default();
29	    test_files += install_tests(&tests.ok, "crates/ruff_python_parser/resources/inline/ok")?;
30	    test_files += install_tests(&tests.err, "crates/ruff_python_parser/resources/inline/err")?;
31	
32	    if !test_files.is_empty() {
33	        anyhow::bail!("{test_files}");
34	    }
35	
36	    Ok(())
37	}
