101	fn install_tests(tests: &HashMap<String, Test>, target_dir: &str) -> Result<TestFiles> {
102	    let root_dir = project_root();
103	    let tests_dir = root_dir.join(target_dir);
104	    if !tests_dir.is_dir() {
105	        fs::create_dir_all(&tests_dir)?;
106	    }
107	
108	    // Test kind is irrelevant for existing test cases.
109	    let existing = existing_tests(&tests_dir)?;
110	
111	    let mut updated_files = vec![];
112	
113	    for (name, test) in tests {
114	        let path = match existing.get(name) {
115	            Some(path) => path.clone(),
116	            None => tests_dir.join(name).with_extension("py"),
117	        };
118	        match fs::read_to_string(&path) {
119	            Ok(old_contents) if old_contents == test.contents => continue,
120	            _ => {}
121	        }
122	        fs::write(&path, &test.contents)
123	            .with_context(|| format!("Failed to write to {:?}", path.display()))?;
124	        updated_files.push(path);
125	    }
126	
127	    Ok(TestFiles {
128	        unreferenced: existing
129	            .into_iter()
130	            .filter(|(name, _)| !tests.contains_key(name))
131	            .map(|(_, path)| path)
132	            .collect::<Vec<_>>(),
133	        updated: updated_files,
134	    })
135	}
