185	/// A test of the following form:
186	///
187	/// ```text
188	/// // (test_ok|test_err) name
189	/// // <code>
190	/// ```
191	#[derive(Debug)]
192	struct Test {
193	    name: String,
194	    contents: String,
195	    kind: TestKind,
196	}
197	
198	impl Test {
199	    const fn is_ok(&self) -> bool {
200	        matches!(self.kind, TestKind::Ok)
201	    }
202	}
