204	/// Collect the tests from the given source text.
205	fn collect_tests(text: &str) -> Vec<Test> {
206	    let mut tests = Vec::new();
207	
208	    for comment_block in extract_comment_blocks(text) {
209	        let first_line = &comment_block[0];
210	
211	        let (kind, name) = match first_line.split_once(' ') {
212	            Some(("test_ok", suffix)) => (TestKind::Ok, suffix),
213	            Some(("test_err", suffix)) => (TestKind::Err, suffix),
214	            _ => continue,
215	        };
216	
217	        let text: String = comment_block[1..]
218	            .iter()
219	            .cloned()
220	            .chain([String::new()])
221	            .collect::<Vec<_>>()
222	            .join("\n");
223	
224	        assert!(!text.trim().is_empty() && text.ends_with('\n'));
225	
226	        tests.push(Test {
227	            name: name.to_string(),
228	            contents: text,
229	            kind,
230	        });
231	    }
232	
233	    tests
234	}
