634	fn collect_unsupported_syntax_errors(
635	    parsed: &Parsed<Mod>,
636	) -> FxHashMap<u64, UnsupportedSyntaxError> {
637	    let mut collected = FxHashMap::default();
638	
639	    if parsed.unsupported_syntax_errors().is_empty() {
640	        return collected;
641	    }
642	
643	    let visitor = StmtVisitor::new(parsed);
644	
645	    for error in parsed.unsupported_syntax_errors() {
646	        let node_id = visitor.node_id(error.range);
647	        let mut error_fingerprint = fingerprint_unsupported_syntax_error(error, node_id, 0);
648	
649	        // Make sure that we do not get a fingerprint that is already in use
650	        // by adding in the previously generated one.
651	        loop {
652	            match collected.entry(error_fingerprint) {
653	                Entry::Occupied(_) => {
654	                    error_fingerprint =
655	                        fingerprint_unsupported_syntax_error(error, node_id, error_fingerprint);
656	                }
657	                Entry::Vacant(entry) => {
658	                    entry.insert(error.clone());
659	                    break;
660	                }
661	            }
662	        }
663	    }

